import jsPDF from 'jspdf';
import { supabase } from './supabase';

// 1. ADIM: KOPYALADIĞIN O DEVASA BASE64 KODUNU BURAYA YAPIŞTIR
// Başında "data:image/jpeg;base64," veya "data:image/png;base64," olduğundan emin ol!
const formTemplateBase64 = "data:image/png;base64,";

// Türkçe karakter filtresi (Sabit)
const tr2en = (text: string) => text.replace(/ğ/g, 'g').replace(/Ğ/g, 'G').replace(/ü/g, 'u').replace(/Ü/g, 'U').replace(/ş/g, 's').replace(/Ş/g, 'S').replace(/ı/g, 'i').replace(/İ/g, 'I').replace(/ö/g, 'o').replace(/Ö/g, 'O').replace(/ç/g, 'c').replace(/Ç/g, 'C');

export const generateAndUploadPdf = async (recordData: any, customer: any, device: any, description: string, price: string) => {
  try {
    // A4 boyutunda dikey (p) PDF oluşturuyoruz
    const doc = new jsPDF('p', 'mm', 'a4');

    // 2. ADIM: ŞABLONU ARKA PLANA YAY (0,0 koordinatından başla, A4 boyutu 210x297 mm'ye uzat)
    doc.addImage(formTemplateBase64, 'JPEG', 0, 0, 210, 297);

    // 3. ADIM: KOORDİNAT BAZLI YAZI DAMGALAMA (X yatay, Y dikey pozisyondur)
    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.setTextColor(20, 20, 20);

    // --- Sağ Üst: Servis Formu Bilgileri ---
    // Bu X ve Y değerlerini (örn: 160, 45) PDF'e baka baka kaydırıp tam çizgiye oturtacaksın.
    doc.text(new Date(recordData.service_date).toLocaleDateString('tr-TR'), 155, 60);
    doc.text(`SRV-${recordData.id.substring(0, 8).toUpperCase()}`, 155, 67);

    // --- Sol Orta: Müşteri Bilgileri ---
    doc.text(tr2en(customer.full_name), 45, 115);
    doc.text(customer.phone_number, 45, 125);
    doc.text(tr2en(customer.address || '-'), 45, 135, { maxWidth: 60 }); // Adres uzunsa alt satıra geçsin diye maxWidth verdik

    // --- Sağ Orta: Cihaz Bilgileri ---
    // Cihaz türüne göre kutucuklara X işareti koyma mantığı
    doc.setFont("helvetica", "bold");
    if (device.device_type === 'Kombi') {
      doc.text("X", 132, 115); // Kombi kutucuğunun tahmini koordinatı
    } else if (device.device_type === 'Klima' || device.device_type === 'VRF Tipi Klima' || device.device_type === 'Salon Tipi Klima') {
      doc.text("X", 152, 115); // Klima kutucuğunun tahmini koordinatı
    } else if (device.device_type === 'Petek') {
      doc.text("X", 175, 115); // Petek kutucuğunun tahmini koordinatı
    }
    
    doc.setFont("helvetica", "normal");
    doc.text(tr2en(`${device.brand} ${device.model}`), 135, 125);
    doc.text(tr2en(device.serial_number || '-'), 135, 135);

    // --- Sol Alt: Arıza / Talep (Açıklama) ---
    // Açıklamayı belirli bir genişlikte (maxWidth) sınırlıyoruz ki taşıp diğer kutulara girmesin
    doc.text(tr2en(description), 15, 160, { maxWidth: 80 });

    // --- Sağ Alt: Yapılan İşlemler (Otomatik Bakım İşareti) ---
    // Örnek: Eğer bakım tarihi verildiyse "Bakım" kutusuna X at
    if (recordData.next_maintenance_date) {
        doc.setFont("helvetica", "bold");
        doc.text("X", 110, 168); // Bakım kutucuğu
        doc.setFont("helvetica", "normal");
    }

    // --- Sağ En Alt: Ücret Bilgisi ---
    doc.text(price ? `${price}` : '0', 170, 235);
    doc.text(price ? `${price}` : '0', 170, 245); // Toplam

    // 4. ADIM: PDF'İ KAYDET VE SUPABASE'E YÜKLE
    const pdfBlob = doc.output('blob');
    const fileName = `vora_servis_${recordData.id}_${Date.now()}.pdf`;

    const { error: uploadError } = await supabase.storage.from('service_pdfs').upload(fileName, pdfBlob, { contentType: 'application/pdf' });
    if (uploadError) throw new Error("Yükleme hatası: " + uploadError.message);

    const { data: urlData } = supabase.storage.from('service_pdfs').getPublicUrl(fileName);
    await supabase.from('service_records').update({ pdf_url: urlData.publicUrl }).eq('id', recordData.id);
    
    return urlData.publicUrl;
  } catch (error) {
    console.error("PDF Üretim Hatası:", error);
    return null;
  }
};